package nhom10.phonenest.service;
import lombok.RequiredArgsConstructor; import nhom10.phonenest.dto.SanPhamDto; import nhom10.phonenest.entity.*; import nhom10.phonenest.exception.AppException; import nhom10.phonenest.mapper.SanPhamMapper; import nhom10.phonenest.repository.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor @Transactional public class KhoService{public static final int NGUONG_SAP_HET=10;private final SanPhamRepository spRepo;private final PhienBanSanPhamRepository pbRepo;public List<SanPhamDto> list(String loc){String f=loc==null?"":loc;return spRepo.findAll().stream().filter(s->s.getPhienBans()!=null&&s.getPhienBans().stream().anyMatch(p->khop(p,f))).sorted(Comparator.comparingInt(SanPham::getSoLuongTon)).map(SanPhamMapper::toDto).toList();}private boolean khop(PhienBanSanPham p,String loc){int t=p.getSoLuongTon();return switch(loc){case "het"->t==0;case "sap-het"->t>0&&t<=NGUONG_SAP_HET;default->true;};}public SanPhamDto nhapKho(String ma,int sl){if(sl<=0)throw new AppException(HttpStatus.BAD_REQUEST,"Số lượng nhập phải lớn hơn 0");PhienBanSanPham p=resolve(ma);p.setSoLuongTon(p.getSoLuongTon()+sl);return SanPhamMapper.toDto(p.getSanPham());}public SanPhamDto datTon(String ma,int sl){if(sl<0)throw new AppException(HttpStatus.BAD_REQUEST,"Tồn kho không được âm");PhienBanSanPham p=resolve(ma);p.setSoLuongTon(sl);return SanPhamMapper.toDto(p.getSanPham());}private PhienBanSanPham resolve(String ma){return pbRepo.findById(ma).orElseThrow(()->new AppException(HttpStatus.NOT_FOUND,"Không tìm thấy phiên bản"));}}
